  const wlTag = wl?.skip_online_analyzers === true && typeof wl.tag === 'string' ? wl.tag : null;
  const ordered = [...e.analyzers.filter((a) => a.severe_path_only !== true), ...e.analyzers.filter((a) => a.severe_path_only === true)];
  let eligible = 0;
  for (const o of observables) {
    const entry = { dataType: o.dataType, data: o.data, tags: o.tags, status: 'skipped', reasons: [], skipped: [], analyzers: [] };
    perObservable.push(entry);
    if (e.enabled !== true) { entry.reasons.push('enrichment disabled in lib-config'); continue; }
    const never = e.skip.never_tags.filter((t) => o.tags.includes(t));
    if (never.length > 0) {
      entry.reasons.push(...never.map((t) => e.skip.reason_by_tag[t] ?? `tag ${t}`));
      continue;
    }
    const localOnly = e.skip.local_only_tags.filter((t) => o.tags.includes(t));
    const supporting = ordered.filter((a) => a.data_types.includes(o.dataType));
    if (supporting.length === 0) { entry.reasons.push(`no analyzer for dataType ${o.dataType}`); continue; }
    const notAbsolute = o.dataType === 'url' && e.url_online_requires_absolute === true && !isAbsoluteHttpUrl(o.data);
    const usable = [];
    const skip = (a, reason) => entry.skipped.push({ analyzer: a.name, reason });
    for (const a of supporting) {
      if (a.enabled !== true) { skip(a, 'disabled in lib-config'); continue; }
      if (tlp > a.max_tlp) { skip(a, `alert TLP ${tlp} above its max ${a.max_tlp}`); continue; }
      if (pap > a.max_pap) { skip(a, `alert PAP ${pap} above its max ${a.max_pap}`); continue; }
      if (a.kind !== 'local' && localOnly.length > 0) { skip(a, `online, and ${localOnly.join(', ')} goes to local analyzers only`); continue; }
      if (a.kind !== 'local' && wlTag !== null && o.tags.includes(wlTag)) { skip(a, `online, and the value is on a MISP warninglist (tag ${wlTag}): local analyzers only`); continue; }
      if (a.kind !== 'local' && notAbsolute) { skip(a, SKIP.urlNotAbsolute); continue; }
