    if (eligible > e.max_observables_per_alert) {
      entry.reasons = [`over max_observables_per_alert (${e.max_observables_per_alert})`];
      entry.skipped = [];
      continue;
    }
    entry.status = 'planned';
    entry.analyzers = usable.map((a) => a.name);
    for (const a of usable) {
      jobs.push({ key: `${o.dataType}:${o.data}`, dataType: o.dataType, data: o.data,
        analyzer: a.name, timeout_s: a.timeout_s, severe_path_only: a.severe_path_only === true,
        tlp, pap, force: e.force === true });
    }
