// Enrichment policy (lib-config `enrichment`), pure: which observable goes to
// which analyzer, and why the others don't. Order of the checks: enrichment
// off; a never-enrich tag; then per analyzer that supports the dataType:
// disabled, TLP / PAP above its max, online on a local-only observable, online
// on a value MISP has on a warninglist (C10; `wl` is lib-config
// misp_warninglist, the tag is set by lib-misp-warninglist), online on a url
// that isn't an absolute http(s) URL with a host (X-44); last, the cap on
// observables per alert (extraction order). Analyzers marked
// severe_path_only (D-N7) are planned last for each observable; whether they
// run is decided before the job (jobGate). An analyzer skip is
// {analyzer, reason}; the writeback shows it as `<analyzer>: skipped (<reason>)`.
const SKIP = {
  notInCortex: 'not enabled in Cortex',
  urlNotAbsolute: 'url not absolute',
  severePath: 'severe path only',
  budget: 'enrichment budget',
};

function isAbsoluteHttpUrl(v) {
  if (typeof v !== 'string' || !/^https?:\/\//i.test(v)) return false;
  try {
    const u = new URL(v);
    return (u.protocol === 'http:' || u.protocol === 'https:') && u.hostname !== '';
  } catch (e) {
    return false;
  }
}

function planEnrichment(observables, e, tlp, pap, wl) {
  const jobs = [];
  const perObservable = [];
  const warnings = [];
  if (e.concurrency !== 1) warnings.push(`enrichment.concurrency ${e.concurrency} is not supported yet: jobs ran one after another`);
  const wlTag = wl?.skip_online_analyzers === true && typeof wl.tag === 'string' ? wl.tag : null;
  const ordered = [...e.analyzers.filter((a) => a.severe_path_only !== true), ...e.analyzers.filter((a) => a.severe_path_only === true)];
  let eligible = 0;
  for (const o of observables) {
    const entry = { dataType: o.dataType, data: o.data, tags: o.tags, status: 'skipped', reasons: [], skipped: [], analyzers: [] };
    perObservable.push(entry);
    if (e.enabled !== true) { entry.reasons.push('enrichment disabled in lib-config'); continue; }
    const never = e.skip.never_tags.filter((t) => o.tags.includes(t));
    if (never.length > 0) {
      entry.reasons.push(...never.map((t) => e.skip.reason_by_tag[t] ?? `tag ${t}`));
      continue;
    }
    const localOnly = e.skip.local_only_tags.filter((t) => o.tags.includes(t));
    const supporting = ordered.filter((a) => a.data_types.includes(o.dataType));
    if (supporting.length === 0) { entry.reasons.push(`no analyzer for dataType ${o.dataType}`); continue; }
    const notAbsolute = o.dataType === 'url' && e.url_online_requires_absolute === true && !isAbsoluteHttpUrl(o.data);
    const usable = [];
    const skip = (a, reason) => entry.skipped.push({ analyzer: a.name, reason });
    for (const a of supporting) {
      if (a.enabled !== true) { skip(a, 'disabled in lib-config'); continue; }
      if (tlp > a.max_tlp) { skip(a, `alert TLP ${tlp} above its max ${a.max_tlp}`); continue; }
      if (pap > a.max_pap) { skip(a, `alert PAP ${pap} above its max ${a.max_pap}`); continue; }
      if (a.kind !== 'local' && localOnly.length > 0) { skip(a, `online, and ${localOnly.join(', ')} goes to local analyzers only`); continue; }
      if (a.kind !== 'local' && wlTag !== null && o.tags.includes(wlTag)) { skip(a, `online, and the value is on a MISP warninglist (tag ${wlTag}): local analyzers only`); continue; }
      if (a.kind !== 'local' && notAbsolute) { skip(a, SKIP.urlNotAbsolute); continue; }
      usable.push(a);
    }
    if (usable.length === 0) continue;
    eligible += 1;
    if (eligible > e.max_observables_per_alert) {
      entry.reasons = [`over max_observables_per_alert (${e.max_observables_per_alert})`];
      entry.skipped = [];
      continue;
    }
    entry.status = 'planned';
    entry.analyzers = usable.map((a) => a.name);
    for (const a of usable) {
      jobs.push({ key: `${o.dataType}:${o.data}`, dataType: o.dataType, data: o.data,
        analyzer: a.name, timeout_s: a.timeout_s, severe_path_only: a.severe_path_only === true,
        tlp, pap, force: e.force === true });
    }
  }
  return { jobs, perObservable, warnings };
}

// One analyzer report -> verdict: each taxonomy level through `levels`, then
// the analyzer's overrides; the worst (highest in `rank`) wins. No taxonomy, or
// only unknown levels -> `empty`.
function verdictOf(analyzer, taxonomies, v) {
  let best = null;
  const unknown = [];
  for (const t of Array.isArray(taxonomies) ? taxonomies : []) {
    let level = v.levels[String(t?.level ?? '').toLowerCase()];
    if (level === undefined) { unknown.push(String(t?.level)); continue; }
    level = v.overrides?.[analyzer]?.[level] ?? level;
    if (best === null || v.rank.indexOf(level) > v.rank.indexOf(best)) best = level;
  }
  return { verdict: best ?? v.empty, unknown };
}

function skippedResult(j, reason) {
  return { kind: 'cortex_job_result', key: j.key, dataType: j.dataType, data: j.data, analyzer: j.analyzer,
    job_id: null, from_cache: false, outcome: 'skipped', reason };
}

// Before each job (D-N7, D-N8): `earlier` = this alert's job results so far.
// A severe_path_only analyzer runs when the alert's severity (as sent to
// TheHive, 1-4) is at least severe_path.min_severity, or when an earlier
// analyzer for the same observable returned one of severe_path.prior_verdicts.
// Then the budget: no job starts once budget_s have passed since the
// enrichment started (a job in flight is never cut).
function jobGate(job, earlier, e, severity, startedMs, nowMs) {
  const elapsed_s = Math.round((nowMs - startedMs) / 100) / 10;
  if (job.severe_path_only === true) {
    const sp = e.severe_path ?? {};
    const bySeverity = typeof severity === 'number' && severity >= sp.min_severity;
    const prior = earlier.filter((r) => r.key === job.key && r.outcome === 'success')
      .map((r) => ({ analyzer: r.analyzer, verdict: verdictOf(r.analyzer, r.taxonomies, e.verdict).verdict }))
      .filter((p) => (sp.prior_verdicts ?? []).includes(p.verdict));
    if (!bySeverity && prior.length === 0) return { run: false, elapsed_s, reason: SKIP.severePath };
    job = { ...job, severe_path: bySeverity ? `severity ${severity}` : prior.map((p) => `${p.analyzer} ${p.verdict}`).join(', ') };
  }
  if (typeof e.budget_s === 'number' && nowMs - startedMs >= e.budget_s * 1000) return { run: false, elapsed_s, reason: SKIP.budget };
  return { run: true, elapsed_s, job };
}

// Plan + job results -> per-observable outcome and the TheHive tag updates.
// A result is `success`, `failed` or `skipped` (no call: not enabled in
// Cortex, severe path only, enrichment budget).
function reduceResults(plan, results, e) {
  const v = e.verdict;
  const byKey = new Map();
  for (const r of results) {
    if (!byKey.has(r.key)) byKey.set(r.key, []);
    byKey.get(r.key).push(r);
  }
  const updates = [];
  const warnings = [];
  const observables = plan.perObservable.map((p) => {
    const skipped = [...(p.skipped ?? [])];
    if (p.status !== 'planned') return { ...p, skipped };
    const rs = byKey.get(`${p.dataType}:${p.data}`) ?? [];
    const ok = [];
    const failed = [];
    for (const r of rs) {
      if (r.outcome === 'success') {
        const { verdict, unknown } = verdictOf(r.analyzer, r.taxonomies, v);
        if (unknown.length > 0) warnings.push(`${r.analyzer} on ${p.data}: unknown taxonomy level(s) ${unknown.join(', ')} ignored`);
        ok.push({ analyzer: r.analyzer, verdict, job_id: r.job_id, from_cache: r.from_cache === true,
          taxonomies: (r.taxonomies ?? []).map((t) => `${t.namespace}:${t.predicate}=${JSON.stringify(t.value)} (${t.level})`) });
      } else if (r.outcome === 'skipped') {
        skipped.push({ analyzer: r.analyzer, reason: r.reason });
      } else {
        failed.push({ analyzer: r.analyzer, class: r.class, attempts: r.attempts ?? null, job_id: r.job_id ?? null, message: r.message ?? null });
      }
    }
    for (const a of p.analyzers) {
      if (!rs.some((r) => r.analyzer === a)) failed.push({ analyzer: a, class: 'no_result', attempts: null, job_id: null, message: 'no result returned' });
    }
    const out = { dataType: p.dataType, data: p.data, tags: p.tags, reasons: p.reasons, results: ok, failed, skipped };
    if (ok.length === 0) return { ...out, status: failed.length > 0 ? 'failed' : 'skipped', verdict: null };
    const verdict = ok.map((x) => x.verdict).reduce((a, b) => (v.rank.indexOf(b) > v.rank.indexOf(a) ? b : a));
    const ioc = e.ioc_verdicts.includes(verdict);
    const addTags = [`${e.tags.verdict_prefix}${verdict}`, ...ok.map((x) => `${e.tags.analyzer_prefix}${x.analyzer}`)];
    updates.push({ key: `${p.dataType}:${p.data}`, dataType: p.dataType, data: p.data, add_tags: addTags, ioc });
    return { ...out, status: 'enriched', verdict, ioc, add_tags: addTags };
  });
  // Analyzer skips by reason, over every observable (plan and run time).
  const skipped_runs = {};
  for (const o of observables) for (const s of o.skipped) skipped_runs[s.reason] = (skipped_runs[s.reason] ?? 0) + 1;
  return { observables, updates, warnings, skipped_runs };
}

// --- this node: job results -> verdict per observable ---------------------
// Reached by exactly one path: no job planned, Cortex unreachable, nothing to
// run after resolving, or the job loop done. Job results (and the gate's
// skips) come as input items; jobs Cortex doesn't list are on the Resolve
// analyzers items.
function gateLog() {
  const out = [];
  if (!$('Job gate').isExecuted) return out;
  for (let r = 0; r < 1000; r++) {
    let items;
    try { items = $('Job gate').all(0, r); } catch (err) { break; }
    for (const it of items) {
      const g = it.json;
      const j = g.gate === 'run' ? g.job : g;
      out.push({ analyzer: j.analyzer, observable: `${j.dataType} ${j.data}`, decision: g.gate === 'run' ? 'run' : `skipped (${g.reason})`,
        elapsed_s: g.elapsed_s, ...(g.gate === 'run' ? { earlier_results: g.earlier_results } : {}),
        ...(j.severe_path ? { severe_path: j.severe_path } : {}) });
    }
  }
  return out;
}
const i = $('Called by a workflow').first().json;
const e = i.config.enrichment;
const plan = $('Plan').first().json;
const results = $input.all().map((x) => x.json).filter((j) => j.kind === 'cortex_job_result');
if ($('Resolve analyzers').isExecuted) results.push(...($('Resolve analyzers').first().json.unresolved ?? []));
const red = reduceResults(plan, results, e);
const ran = results.filter((r) => r.outcome !== 'skipped');
const budgetSkipped = red.skipped_runs[SKIP.budget] ?? 0;
return [{ json: { ...red, jobs: ran.length, jobs_planned: plan.jobs.length, jobs_from_cache: ran.filter((r) => r.from_cache).length,
  cortex_called: $('List Cortex analyzers').isExecuted, severity: plan.severity,
  budget: { budget_s: e.budget_s ?? null, started_ms: plan.started_ms, used_s: Math.round((Date.now() - plan.started_ms) / 100) / 10,
    hit: budgetSkipped > 0, skipped: budgetSkipped },
  job_log: gateLog(), warnings: [...plan.warnings, ...red.warnings] } }];

// Retry policy for TheHive calls (N8N-6.2; lib-config thehive_http): a
// connection error, a timeout or HTTP 5xx -> wait and call again; anything
// else (2xx, and 4xx, which a retry never fixes) -> passed on. A transient
// failure on the last call is passed on as an error with the number of calls.
const r = $input.first().json;
const policy = $('Called by a workflow').first().json.config.thehive_http;
const NODE = 'Fetch alert observables';
const attempt = $runIndex + 1; // this node runs once per call
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|EHOSTUNREACH|ENETUNREACH|ECONNABORTED|timeout|timed out|socket hang up|connection cannot be established/i;
const transient = thrown ? NETWORK.test(JSON.stringify(r)) : status >= 500;
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { decision: 'retry', stage: NODE, attempt, wait_s: policy.retry_waits_s[attempt - 1],
    reason: thrown ? 'connection error or timeout' : `HTTP ${status}` } }];
}
if (thrown || transient) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || JSON.stringify(r))
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { decision: 'error', stage: NODE, node: NODE, attempts: attempt, retry_exhausted: transient,
    http_status: status, error_code: e?.code ?? e?.cause?.code ?? null,
    message: `${detail}`.slice(0, 1000) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { ...r, decision: 'response', attempts: attempt } }];

// TheHive 5.7.6 returns an alert's observables (with their _id) through the
// query API: getAlert -> observables. Matched on dataType + data.
const r = $input.first().json;
const i = $('Called by a workflow').first().json;
const updates = $('Reduce').first().json.updates;
if (!(r.statusCode >= 200 && r.statusCode < 300) || !Array.isArray(r.body)) {
  const cls = r.statusCode >= 400 && r.statusCode < 500 ? 'thehive_4xx' : 'thehive_error';
  return [{ json: { nothing_to_tag: true, not_tagged: updates.map((u) => ({ key: u.key, class: cls, message: `observable lookup: HTTP ${r.statusCode}` })) } }];
}
const idByKey = new Map(r.body.map((o) => [`${o.dataType}:${o.data}`, o._id]));
const not_tagged = updates.filter((u) => !idByKey.has(u.key))
  .map((u) => ({ key: u.key, class: 'observable_not_found', message: `${u.key} not found on alert ${i.thehive_alert_id}` }));
const toTag = updates.filter((u) => idByKey.has(u.key));
if (toTag.length === 0) return [{ json: { nothing_to_tag: true, not_tagged } }];
return toTag.map((u) => ({ json: { observable_id: idByKey.get(u.key), dataType: u.dataType, data: u.data,
  add_tags: u.add_tags, ioc: u.ioc, thehive_http: i.config.thehive_http, not_tagged } }));

// Reached by exactly one path: nothing to tag, the observable lookup failed
// for good, nothing matched, or the tag loop done.
const red = $('Reduce').first().json;
const inputs = $input.all().map((x) => x.json);
const tagResults = inputs.filter((j) => j.kind === 'tag_result');
const lookupError = inputs.find((j) => j.decision === 'error');
const notTagged = new Map();
if ($('Match observables').isExecuted) for (const n of $('Match observables').first().json.not_tagged ?? []) notTagged.set(n.key, n);
if (lookupError) {
  for (const u of red.updates) notTagged.set(u.key, { key: u.key, class: lookupError.retry_exhausted ? 'thehive_unreachable' : 'thehive_error',
    attempts: lookupError.attempts ?? null, message: lookupError.message ?? null });
}
for (const t of tagResults) {
  if (!t.ok) notTagged.set(`${t.dataType}:${t.data}`, { class: t.class, attempts: t.attempts, message: t.message });
}
const observables = red.observables.map((o) => {
  if (o.status !== 'enriched') return o;
  const n = notTagged.get(`${o.dataType}:${o.data}`);
  return { ...o, tagged: !n, tag_error: n ? { class: n.class, attempts: n.attempts ?? null, message: n.message ?? null } : null };
});
const count = (s) => observables.filter((o) => o.status === s).length;
return [{ json: {
  ok: true,
  // skipped_runs: analyzer skips by reason (not enabled in Cortex, url not
  // absolute, severe path only, enrichment budget, and the plan's others).
  counts: { observables: observables.length, enriched: count('enriched'), skipped: count('skipped'), failed: count('failed'),
    jobs: red.jobs, jobs_planned: red.jobs_planned, jobs_from_cache: red.jobs_from_cache, skipped_runs: red.skipped_runs,
    tagged: observables.filter((o) => o.tagged === true).length,
    not_tagged: observables.filter((o) => o.tagged === false).length },
  cortex_called: red.cortex_called,
  severity: red.severity,
  budget: red.budget,
  observables,
  job_log: red.job_log,
  warnings: red.warnings,
} }];
